SELECT COALESCE(SUM(CASE WHEN status = 'PAID' THEN amount ELSE 0 END), 0) AS totalPaid, COALESCE(SUM(CASE WHEN status = 'UNPAID' THEN amount ELSE 0 END), 0) AS totalUnpaid, COALESCE(SUM(CASE WHEN status = 'PAID' THEN 1 ELSE 0 END), 0) AS countPaid, COALESCE(SUM(CASE WHEN status = 'UNPAID' THEN 1 ELSE 0 END), 0) AS countUnpaid FROM payments
AND COALESCE(paid_date, due_date) >= #{from}
AND COALESCE(paid_date, due_date) <= #{to}

SELECT COUNT(*) FROM students
AND created_at >= #{from}
AND created_at < (CAST(#{to} AS DATE) + INTERVAL '1 day')
